import math
def arc(v, delta, t, L=2.8):
    kappa = math.tan(delta) / L
    psi = v * kappa * t
    if abs(kappa) < 1e-12:
        return (v*t, 0.0, psi)
    return (math.sin(psi)/kappa, (1-math.cos(psi))/kappa, psi)

